/* Page sections. Each block is used by the page named in its comment. */

/* Home */

.hero {
  position: relative;
  overflow: hidden;
  padding: var(--space-8) 0 calc(var(--space-8) + 56px);
  border-bottom: 1px solid var(--color-line);
  background: linear-gradient(180deg, var(--color-brand-tint), var(--color-bg));
}

.hero::before {
  content: '';
  position: absolute;
  top: -140px;
  right: -100px;
  width: 460px;
  height: 460px;
  border-radius: 50%;
  background: radial-gradient(closest-side, rgba(6, 182, 212, 0.2), rgba(6, 182, 212, 0));
}

.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: var(--space-7);
  align-items: center;
}

.hero-copy h1 {
  font-size: 44px;
}

.hero-copy .lede {
  max-width: 480px;
  margin-top: var(--space-4);
}

.hero-actions {
  display: flex;
  gap: var(--space-3);
  margin-top: var(--space-5);
}

.stats-overlap {
  position: relative;
  z-index: 1;
  margin-top: -56px;
}

.feature {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: var(--space-6);
  align-items: center;
  overflow: hidden;
}

.feature-art {
  height: 260px;
  background: linear-gradient(135deg, #0ea5e9, #6366f1);
}

.feature-copy {
  padding: var(--space-5) var(--space-5) var(--space-5) 0;
}

.feature-copy h3 {
  font-size: 22px;
}

.feature-copy .price {
  margin: var(--space-3) 0 var(--space-4);
}

.newsletter {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-6);
  align-items: center;
  padding: var(--space-6);
}

.form-note {
  margin-top: var(--space-2);
  font-size: 13px;
}

/* Products */

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-bottom: var(--space-5);
}

.chip {
  padding: 6px 14px;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-pill);
  background: var(--color-surface);
  font-size: 14px;
  font-weight: 600;
  color: var(--color-muted);
}

.chip.is-active {
  border-color: var(--color-ink);
  background: var(--color-ink);
  color: #ffffff;
}

.thumb-1 {
  background: linear-gradient(135deg, #0ea5e9, #6366f1);
}

.thumb-2 {
  background: linear-gradient(135deg, #f59e0b, #ef4444);
}

.thumb-3 {
  background: linear-gradient(135deg, #10b981, #0e7490);
}

.thumb-4 {
  background: linear-gradient(135deg, #a855f7, #ec4899);
}

.thumb-5 {
  background: linear-gradient(135deg, #64748b, #0f172a);
}

.thumb-6 {
  background: linear-gradient(135deg, #facc15, #84cc16);
}

.bundles {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-5);
}

/* Pricing */

.plans {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-5);
  align-items: start;
  padding-top: var(--space-4);
}

.plan {
  position: relative;
  padding: var(--space-5);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-lg);
  background: var(--color-surface);
}

.plan-featured {
  border: 2px solid var(--color-brand);
  box-shadow: var(--shadow-md);
}

.plan-ribbon {
  position: absolute;
  top: -13px;
  left: 50%;
  z-index: 1;
  padding: 3px 12px;
  border-radius: var(--radius-pill);
  background: var(--color-brand);
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  transform: translateX(-50%);
}

.plan-price {
  margin: var(--space-3) 0;
  font-size: 40px;
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.plan-price small {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0;
  color: var(--color-muted);
}

.plan-features {
  margin: var(--space-4) 0 var(--space-5);
}

.plan-features li {
  padding: var(--space-2) 0;
  border-top: 1px solid var(--color-line);
  font-size: 15px;
}

.plan .btn {
  width: 100%;
}

.faq {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-5);
}

.faq-item h3 {
  margin-bottom: var(--space-2);
}

.faq-item p {
  font-size: 15px;
  color: var(--color-muted);
}

/* Orders */

.table-tools {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: var(--space-4);
  font-size: 14px;
  color: var(--color-muted);
}

.pager {
  display: flex;
  gap: var(--space-2);
}

/* Contact */

.contact-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: var(--space-6);
  align-items: start;
}

.info-list dt {
  margin-top: var(--space-4);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--color-muted);
}

.info-list dt:first-child {
  margin-top: 0;
}

.info-list dd {
  overflow-wrap: anywhere;
}

/* About */

.story {
  display: grid;
  grid-template-columns: 1fr 480px;
  gap: var(--space-7);
  align-items: center;
}

.story p + p {
  margin-top: var(--space-4);
}

.story-art {
  border-radius: var(--radius-lg);
}

.avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: var(--space-3);
  border-radius: 50%;
  background: var(--color-brand-tint);
  font-size: 18px;
  font-weight: 800;
  color: var(--color-brand-dark);
}

.timeline {
  padding-left: var(--space-5);
  border-left: 2px solid var(--color-line);
}

.timeline-item {
  position: relative;
  padding-bottom: var(--space-5);
}

.timeline-item:last-child {
  padding-bottom: 0;
}

.timeline-item::before {
  content: '';
  position: absolute;
  top: 5px;
  left: -32px;
  width: 12px;
  height: 12px;
  border: 2px solid var(--color-surface);
  border-radius: 50%;
  background: var(--color-brand);
}

.timeline-year {
  font-weight: 800;
  color: var(--color-brand);
}

.cta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
  padding: var(--space-6);
  border-radius: var(--radius-lg);
  background: var(--color-ink);
  color: #ffffff;
}

.cta p {
  margin-top: var(--space-1);
  color: #c9d1d9;
}

@media (max-width: 720px) {
  .hero {
    padding-top: var(--space-7);
  }

  .hero-inner,
  .feature,
  .newsletter,
  .bundles,
  .plans,
  .faq,
  .contact-grid,
  .story {
    grid-template-columns: 1fr;
  }

  .hero-copy h1 {
    font-size: 32px;
  }

  .feature-copy {
    padding: 0 var(--space-5) var(--space-5);
  }

  .feature-art {
    height: 160px;
  }

  .newsletter {
    padding: var(--space-5);
  }

  .cta {
    flex-direction: column;
    align-items: flex-start;
  }
}

